<?= view('layout/header') ?><?php $editing=$user!==null; ?><h1><?= $editing?'Edit User':'New User' ?></h1><form method="post" enctype="multipart/form-data" action="<?= site_url($editing?'users/'.$user['id']:'users') ?>"><?= csrf_field() ?>
<label>Username *</label><input name="username" required maxlength="80" value="<?= esc(old('username',$user['username']??''),'attr') ?>"><p class="error"><?= esc($errors['username']??'') ?></p>
<label>Full name *</label><input name="full_name" required maxlength="150" value="<?= esc(old('full_name',$user['full_name']??''),'attr') ?>"><p class="error"><?= esc($errors['full_name']??'') ?></p>
<?php if($editing): ?><label>Profile picture (JPG or PNG, up to 2 MB)</label><input type="file" name="avatar" accept=".jpg,.jpeg,.png,image/jpeg,image/png"><p class="error"><?= esc($errors['avatar']??'') ?></p><?php if($user['avatar']): ?><img class="avatar" alt="Current avatar" src="<?= base_url('uploads/avatars/'.rawurlencode($user['avatar'])) ?>"><?php endif; ?><?php else: ?><p><small>You can upload an avatar after creating the user, on the edit page.</small></p><?php endif; ?>
<button>Save User</button> <a href="<?= site_url('users') ?>">Cancel</a></form><?= view('layout/footer') ?>
